param([Parameter(Mandatory)][ValidateSet('collection-idle','final-normal')][string]$Mode)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
. "$PSScriptRoot/afternoon-runtime-helpers.ps1"
. "$PSScriptRoot/observe-october16-v22-repeat-progress.ps1"
function Get-Phase08October16FinalProfileSql($Definitions){
 if(@($Definitions).Count -ne 3 -or @($Definitions|ForEach-Object {$_.key}|Sort-Object -Unique).Count -ne 3){throw 'definitions'};$values=@()
 $fixed=@{'phase08-cafe24'=@('0c35defe-45fc-4a54-bc79-704df7bca5b1','CAFE24',110,@('2026-10-16T01:15:00.000Z','2026-10-14T17:00:00.000Z'));'phase08-google'=@('b9ebee4b-5d4e-4eae-92b9-9facfbf3c900','GOOGLE',90,@('2026-10-14T17:01:00.000Z'));'phase08-meta'=@('1277dc2a-ea20-41eb-8a1c-ab1bfcc564f6','META',90,@('2026-10-16T03:30:00.000Z','2026-10-15T17:02:00.000Z'))}
 foreach($d in $Definitions){if($d.key -isnot [string] -or -not $fixed.ContainsKey($d.key)){throw 'fixed-key'};$b=$fixed[$d.key];if($d.connectionId -cne $b[0] -or $d.provider -cne $b[1] -or $d.windowMinutes -ne $b[2] -or $d.anchorAt -cnotin $b[3]){throw 'fixed-scope'}}
 foreach($d in $Definitions){if($d.key -cnotin @('phase08-cafe24','phase08-google','phase08-meta') -or $d.connectionId -isnot [string] -or $d.connectionId -cnotmatch '^[a-f0-9-]{36}$' -or $d.provider -cnotin @('CAFE24','GOOGLE','META') -or $d.timeZone -cne 'Asia/Seoul' -or $d.targetId -cne 'phase08-full-app' -or $d.anchorAt -isnot [string] -or $d.anchorAt -cnotmatch '^2026-10-\d\dT\d\d:\d\d:00\.000Z$' -or ($d.windowMinutes -isnot [int] -and $d.windowMinutes -isnot [long]) -or $d.windowMinutes -notin @(90,110)){throw 'definition-field'};$cadence=if($d.provider -ceq 'CAFE24'){1}else{7};$values+="('$($d.key)','$($d.connectionId)'::uuid,'$($d.provider)','$($d.anchorAt)'::timestamptz,$($d.windowMinutes),$cadence)"}
 return "BEGIN READ ONLY;SET LOCAL statement_timeout=15000;SET LOCAL TIME ZONE 'UTC';WITH expected(key,connection_id,provider,anchor_at,window_minutes,cadence_days) AS(VALUES $($values -join ',')) SELECT current_database()='postgres' AND current_user='postgres' AND current_setting('transaction_read_only')='on' AND to_regnamespace('storage_renewal_ops') IS NULL AS identity,(SELECT count(*)::int FROM daily_data_sync_ops.schedules) AS schedules,(SELECT count(*)::int FROM daily_data_sync_ops.schedules WHERE paused) AS paused,(SELECT count(*)::int FROM daily_data_sync_ops.schedules s JOIN expected e ON s.key=e.key AND s.connection_id=e.connection_id AND s.provider=e.provider AND s.anchor_at=e.anchor_at AND s.window_minutes=e.window_minutes AND s.cadence_days=e.cadence_days) AS matched,(SELECT md5(prosrc) FROM pg_proc WHERE oid='daily_data_sync_ops.call(text,boolean)'::regprocedure) AS call_md5;COMMIT;"
}
function Assert-Phase08October16IdleReceipt($Pins,$Mode){
 $kind=if($Mode -ceq 'collection-idle'){'initial'}else{'normal'};$file=Get-Item -LiteralPath ("C:/Users/seong/AppData/Local/MetaAdsPhase08Evaluation/october16-v22-deployment-$kind-actual-20261016.json")
 if($file.PSIsContainer -or ($file.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 -or $file.Length -gt 16384){throw 'receipt-file'};$r=[IO.File]::ReadAllText($file.FullName)|ConvertFrom-Json -AsHashtable -DateKind String -Depth 10
 if($r.state -cne 'PHASE08_OCTOBER16_DEPLOYMENT_VERIFIED' -or $r.action -cne $kind -or $r.sourceSha -cne $Pins.sourceSha -or $r.deploymentId -cne $Pins.deploymentId -or $r.region -cne 'sin'){throw 'receipt'}
 $observed=[DateTimeOffset]::MinValue;if($r.observedAt -isnot [string] -or -not [DateTimeOffset]::TryParse($r.observedAt,[ref]$observed) -or $observed -lt [DateTimeOffset]'2026-10-16T03:30:00Z' -or $observed -gt [DateTimeOffset]::UtcNow){throw 'receipt-time'}
 foreach($n in @('resourceConfigurationPreserved','sleepApplication','globalStopped')){if($r[$n] -isnot [bool] -or -not $r[$n]){throw 'receipt-bool'}}
 foreach($p in @(@('immutableFiles',475),@('databaseForceRls',68),@('liveLeasesObserved',0),@('replicas',1),@('cpu',1),@('memoryBytes',1000000000))){$n=$p[0];if(($r[$n] -isnot [int] -and $r[$n] -isnot [long]) -or $r[$n] -ne $p[1]){throw 'receipt-count'}}
 if($kind -ceq 'initial'){if($Pins.deploymentId -cne '25e68a9b-04f6-4329-b6bd-b5a3391fb01c' -or $r.previousDeploymentId -cne '5b6caf98-f569-4c6e-9086-2401cae2dd7b' -or $r.frozenSourceNewBuild -isnot [bool] -or -not $r.frozenSourceNewBuild){throw 'initial-receipt'}}else{if($r.previousDeploymentId -cne '25e68a9b-04f6-4329-b6bd-b5a3391fb01c' -or $r.previousDeploymentId -ceq $r.deploymentId -or $r.sameImageVerified -isnot [bool] -or -not $r.sameImageVerified -or $r.frozenSourceNewBuild -isnot [bool] -or $r.frozenSourceNewBuild){throw 'normal-receipt'}}
}
$stage='IDENTITY';$context=$null
try{
 Import-Phase08SchedulerChildDefinitions;$pins=Get-Phase08SchedulerPins;if($pins.sourceSha -cne '0f790d901c949fc456dce6ab863b4bccca10a212b7c7b75afb03f52a0979fdc1'){throw 'source'};$context=Read-Phase08ProtectedJson;Assert-Phase08SchedulerContext $context $pins
 $output=Assert-Phase08SchedulerOutputPath ("C:/Users/seong/AppData/Local/MetaAdsPhase08Evaluation/october16-v22-$Mode-state-actual-20261016.json")
 $stage='REVIEWED_DEPLOYMENT_RECEIPT';Assert-Phase08October16IdleReceipt $pins $Mode
 $phase=if($Mode -ceq 'collection-idle'){'test'}else{'normal'};$profile=Invoke-Phase08ConfigurationChild "$PSScriptRoot/october16-repeat-profile-bridge.mjs" @{action='definitions';phase=$phase}
 $stage='GRAPH_READONLY';$graph=Get-Phase08SchedulerGraphState $context $pins
 if($graph.deploymentStatus -cne 'SLEEPING' -or $graph.featureEnabled -isnot [bool] -or -not $graph.featureEnabled -or $graph.scheduleEnabled -isnot [bool] -or -not $graph.scheduleEnabled -or $profile.state -cne 'PHASE08_OCTOBER16_DEFINITIONS' -or @($profile.definitions).Count -ne 3 -or @($graph.appSchedules).Count -ne 3){throw 'graph'}
 foreach($d in $profile.definitions){$r=@($graph.appSchedules|Where-Object {$_.key -ceq $d.key});if($r.Count -ne 1 -or $r[0].Count -ne 4 -or $r[0].connectionId -cne $d.connectionId -or $r[0].anchorAt -cne $d.anchorAt -or ($r[0].windowMinutes -isnot [int] -and $r[0].windowMinutes -isnot [long]) -or $r[0].windowMinutes -ne $d.windowMinutes){throw 'app-definitions'}}
 $stage='DATABASE_READONLY';$snapshot=Get-Phase08AfternoonRuntimeSnapshot
 $wantStopped=$Mode -ceq 'collection-idle';if($snapshot.stopped -isnot [bool] -or $snapshot.stopped -cne $wantStopped -or $snapshot.active_jobs -ne 149 -or $snapshot.live_leases -ne 0){throw 'snapshot'}
 $rows=@(Invoke-Phase08Management -Action Query -Query (Get-Phase08October16FinalProfileSql $profile.definitions));if($rows.Count -ne 1){throw 'profile-rows'};$r=$rows[0];$names=@('identity','schedules','paused','matched','call_md5');$keys=if($r -is [Collections.IDictionary]){@($r.Keys)}else{@($r.PSObject.Properties.Name)};if($keys.Count -ne 5 -or @($keys|Where-Object{$_ -cnotin $names}).Count -ne 0 -or $r.identity -isnot [bool] -or -not $r.identity){throw 'profile-shape'}
 foreach($p in @(@('schedules',3),@('paused',0),@('matched',3))){$n=$p[0];if(($r.$n -isnot [int] -and $r.$n -isnot [long]) -or $r.$n -ne $p[1]){throw 'profile-count'}};$call=if($Mode -ceq 'collection-idle'){'e53b9aad9453733a4113c09d0ee69657'}else{'0f11e36961a628ab665302b950d0b9aa'};if($r.call_md5 -cne $call){throw 'call'}
 $stage='COMPLETED_AND_IDLE';$progress=ConvertTo-Phase08October16Progress @(Invoke-Phase08Management -Action Query -Query (Get-Phase08October16ProgressSql)) $graph.deploymentStatus
 foreach($n in @('cafe_checkpoints','meta_checkpoints','active_leases','runtime_active','runtime_idle','runtime_total')){if($progress[$n] -ne 0){throw 'not-idle'}}
 if($progress.cafe.status -cne 'SUCCEEDED' -or $progress.cafe.published -ne 379 -or $progress.meta.status -cne 'SUCCEEDED' -or @($progress.meta.units).Count -ne 7 -or @($progress.meta.units|Where-Object {$_.status -cne 'SUCCEEDED'}).Count -ne 0){throw 'not-complete'}
 $out=@{state='PHASE08_OCTOBER16_FINAL_STATE_READONLY_VERIFIED';verified=$true;mode=$Mode;sourceSha=$pins.sourceSha;deploymentId=$pins.deploymentId;observedAt=[DateTimeOffset]::UtcNow.ToString('o');profile=$phase;appDatabaseDefinitionsMatch=$true;callMd5=$call;totalJobs=149;activeJobs=149;pausedSchedules=0;globalStopped=$wantStopped;forceRlsTables=68;liveLeases=0;currentRunCheckpoints=0;runtimeBackendConnections=0;deploymentStatus='SLEEPING';original152Preserved=$true;cafePublishedRows=379;metaSuccessfulUnits=7;appHttpRequests=0;providerRequests=0;databaseWrites=0;rawValuesReturned=0;runtimeConnectionScope='SUPAVISOR_BACKEND_OBSERVATION'}
 $null=Write-Phase08SchedulerPublicEvidence $out $output;$out|ConvertTo-Json -Compress
}catch{@{state='PHASE08_OCTOBER16_FINAL_STATE_REJECTED';stage=$stage;mode=$Mode;providerRequests=0;appHttpRequests=0;databaseWrites=0;rawErrorSuppressed=$true;retryPerformed=$false}|ConvertTo-Json -Compress;exit 1}finally{$context=$null;$rows=$null;$progress=$null;$snapshot=$null;$out=$null}
